// Convert Microsoft fxc/D3DDisassemble text into the DXC-style disassembly that
// RenoDX's decompiler (src/utils/shader_decompiler_dxc.hpp) tokenizes:
//   * comment marker "//" becomes ";"
//   * the "Generated by ..." banner line is dropped
//   * byte-offset prefixes on instruction lines are stripped
//   * trailing "// Approximately N instruction slots used" is dropped
// This is a text-format adapter only; it does not alter any instruction.
import fs from 'node:fs';

const [, , inputPath, outputPath] = process.argv;
if (!inputPath || !outputPath) {
  throw new Error('Usage: node convert-fxc-to-dxc.mjs <fxc.asm> <dxc-style.asm>');
}

const raw = fs.readFileSync(inputPath, 'utf8');
const lines = raw.split('\n');
const out = [];

for (const line of lines) {
  // Drop the generator banner and the trailing statistics line.
  if (/Generated by Microsoft \(R\) D3D Shader Disassembler/.test(line)) continue;
  if (/^\/\/\s*Approximately .* instruction slots used/.test(line)) continue;

  // Instruction lines: "   12  0x00000280:   mul r1.x, r1.x, l(0.159302)"
  const instruction = line.match(/^\s*\d+\s+0x[0-9A-Fa-f]+:\s?(.*)$/);
  if (instruction) {
    out.push(instruction[1].trimEnd());
    continue;
  }

  // Declaration lines: "      0x0000000C: dcl_constantbuffer CB0[22:22][11], ..."
  const declaration = line.match(/^\s*0x[0-9A-Fa-f]+:\s?(.*)$/);
  if (declaration) {
    out.push(declaration[1].trimEnd());
    continue;
  }

  // Remaining comment lines: "// Input signature:" -> "; Input signature:"
  out.push(line.replace(/^\/\//, ';').trimEnd());
}

fs.writeFileSync(outputPath, out.join('\n'));
console.log(`Wrote ${outputPath} (${out.length} lines)`);
